from dataclasses import dataclass, field


@dataclass
class Product:
    sku: str
    price_cents: int
    currency: str = 'USD'

    # BEGIN USER CODE Product
    def validate(self):
        return self.price_cents >= 0 and len(self.sku) > 0
    # END USER CODE Product


@dataclass
class Coupon:
    code: str
    percent_off: int

    # BEGIN USER CODE Coupon
    def validate(self):
        return 0 < self.percent_off <= 100
    # END USER CODE Coupon

import unittest
from models.entities import Product, Coupon
class T(unittest.TestCase):
    def test_max_uses(self):
        self.assertEqual(Coupon(code="X", percent_off=10).max_uses, 1)
        self.assertTrue(Coupon(code="X", percent_off=10, max_uses=5).validate())
        self.assertFalse(Coupon(code="X", percent_off=10, max_uses=0).validate())
    def test_percent(self):
        self.assertFalse(Coupon(code="X", percent_off=0).validate())

